<script setup lang="ts">
import {computed} from 'vue'
import {Table as ATable,Tag as ATag} from 'ant-design-vue'
import {watchlistKinds,watchlistMatchTypes,watchlistState,watchlistStates,type WatchlistRecord} from '../watchlists'
import {formatTime} from '../types'
const props=defineProps<{items:readonly WatchlistRecord[];canEdit:boolean;disabled?:boolean;now?:number}>()
const emit=defineEmits<{inspect:[record:WatchlistRecord];edit:[record:WatchlistRecord];preview:[record:WatchlistRecord];state:[record:WatchlistRecord]}>()
const rows=computed(()=>[...props.items])
const columns=[{title:'名单',key:'name',width:210},{title:'匹配方式 / 值',key:'values',width:250},{title:'探针范围',key:'scope',width:120},{title:'业务有效期',key:'period',width:190},{title:'当前状态',key:'state',width:110},{title:'修订',dataIndex:'revision',width:70},{title:'操作',key:'actions',width:240,fixed:'right' as const}]
</script>
<template><div class="table-wrap"><a-table :columns="columns" :data-source="rows" row-key="id" size="small" :pagination="false" :scroll="{x:1190}"><template #bodyCell="{column,record}"><template v-if="column.key==='name'"><strong class="watchlist-wrap">{{record.name}}</strong><div class="page-description">{{watchlistKinds[(record as WatchlistRecord).definition.kind]}}</div></template><template v-else-if="column.key==='values'"><span>{{watchlistMatchTypes[(record as WatchlistRecord).definition.match_type]}}</span><div class="technical watchlist-wrap">{{record.definition.values.slice(0,2).join('、')}}</div><span v-if="record.definition.values.length>2" class="page-description">另 {{record.definition.values.length-2}} 项</span></template><template v-else-if="column.key==='scope'">{{record.definition.sensors.length}} 个指定探针</template><template v-else-if="column.key==='period'"><div>{{formatTime(record.definition.valid_from)}}</div><div class="page-description">至 {{formatTime(record.definition.valid_until)}}</div></template><a-tag v-else-if="column.key==='state'" :color="watchlistState(record as WatchlistRecord,now)==='effective'?'success':watchlistState(record as WatchlistRecord,now)==='expired'?'warning':undefined">{{watchlistStates[watchlistState(record as WatchlistRecord,now)]}}</a-tag><div v-else-if="column.key==='actions'" class="watchlist-actions"><a-button type="link" size="small" :disabled="disabled" @click="emit('inspect',record as WatchlistRecord)">查看</a-button><a-button v-if="canEdit" type="link" size="small" :disabled="disabled" @click="emit('edit',record as WatchlistRecord)">编辑</a-button><a-button v-if="canEdit" type="link" size="small" :disabled="disabled" @click="emit('preview',record as WatchlistRecord)">范围核验</a-button><a-button v-if="canEdit" type="link" size="small" :disabled="disabled" @click="emit('state',record as WatchlistRecord)">{{record.active?'停用':'启用'}}</a-button></div></template></a-table></div></template>
<style scoped>.watchlist-actions{display:flex;align-items:center;gap:4px;flex-wrap:wrap}.watchlist-wrap{overflow-wrap:anywhere}</style>
